// Detailed weapon viewmodels + remote guns with REAL image-based PBR textures.
// Texture assets: public/assets/textures/weapons/<key>.jpg + <key>_n.jpg (normal) + <key>_r.jpg (roughness),
// generated by scripts/texgen/gen.sh (z-ai image gen) and processed by scripts/texgen/process.py
// (2x2 mirror tileable, sobel normals, baked absolute roughness).
//
// Design goals:
//  - MeshStandardMaterial with albedo/normal/roughness maps for real PBR response
//  - graceful degradation: materials show flat fallback colors until textures load
//    (and keep them forever if the images 404)
//  - per-part texture repeat derived from geometry size (uniform texel density)
//  - material + geometry caches keep draw setup cheap; texture clones share one GPU upload
import * as THREE from 'three'
import type { TeamId, WeaponId } from './weapons'

export interface ViewModel {
  group: THREE.Group
  /** muzzle tip, local to group */
  tip: THREE.Vector3
  /** magazine (hidden mid-reload, dropped copy spawned by engine) */
  mag?: THREE.Group
  /** pistol slide (blowback anim) */
  slide?: THREE.Mesh
  /** AWP bolt assembly (cycle anim) */
  bolt?: THREE.Group
  /** shell ejection port, local to group */
  eject?: THREE.Vector3
  /** C4 blinking LED */
  led?: THREE.Mesh
  muzzleLen?: number
}

export type TexKey =
  | 'steel_blued' | 'polymer_black' | 'wood_laminate' | 'enamel_od'
  | 'metal_dark' | 'glove_fabric' | 'pcb_green'

const TEX_DIR = '/assets/textures/weapons'

interface MatOpts {
  color?: number
  metalness?: number
  /** multiplies the baked roughness map once applied */
  roughnessMul?: number
  normalScale?: number
  /** texture tiles per meter override */
  density?: number
  rx?: number
  ry?: number
}

interface TexEntry {
  albedo: THREE.Texture
  normal: THREE.Texture
  rough: THREE.Texture
  ready: boolean
  pending: Array<{ mat: THREE.MeshStandardMaterial; rx: number; ry: number; o: MatOpts }>
}

const loader = new THREE.TextureLoader()
const texDB = new Map<TexKey, TexEntry>()

const FALLBACK: Record<TexKey, { color: number; metalness: number; roughness: number; density: number }> = {
  steel_blued:   { color: 0x33383d, metalness: 0.90, roughness: 0.40, density: 2.6 },
  polymer_black: { color: 0x232629, metalness: 0.15, roughness: 0.80, density: 7.0 },
  wood_laminate: { color: 0x8a5426, metalness: 0.05, roughness: 0.60, density: 2.8 },
  enamel_od:     { color: 0x4c5442, metalness: 0.35, roughness: 0.50, density: 2.6 },
  metal_dark:    { color: 0x2b2f33, metalness: 0.85, roughness: 0.55, density: 3.0 },
  glove_fabric:  { color: 0x1a1c1f, metalness: 0.00, roughness: 0.90, density: 6.5 },
  pcb_green:     { color: 0x1c3a26, metalness: 0.30, roughness: 0.60, density: 4.0 },
}

function getTex(key: TexKey): TexEntry {
  let e = texDB.get(key)
  if (e) return e
  let remaining = 3
  const onOne = () => {
    remaining--
    if (remaining <= 0) flush(key)
  }
  // onError also counts down -> failed loads keep the flat color fallback
  const load = (file: string) => loader.load(`${TEX_DIR}/${file}`, onOne, undefined, onOne)
  e = { albedo: load(`${key}.jpg`), normal: load(`${key}_n.jpg`), rough: load(`${key}_r.jpg`), ready: false, pending: [] }
  texDB.set(key, e)
  return e
}

function applyMaps(key: TexKey, mat: THREE.MeshStandardMaterial, rx: number, ry: number, o: MatOpts) {
  const e = getTex(key)
  const alb = e.albedo.clone()
  alb.wrapS = alb.wrapT = THREE.RepeatWrapping
  alb.repeat.set(rx, ry)
  alb.colorSpace = THREE.SRGBColorSpace
  alb.anisotropy = 4
  const nrm = e.normal.clone()
  nrm.wrapS = nrm.wrapT = THREE.RepeatWrapping
  nrm.repeat.set(rx, ry)
  nrm.anisotropy = 4
  const rgh = e.rough.clone()
  rgh.wrapS = rgh.wrapT = THREE.RepeatWrapping
  rgh.repeat.set(rx, ry)
  mat.map = alb
  mat.normalMap = nrm
  mat.roughnessMap = rgh
  const ns = o.normalScale ?? 1
  mat.normalScale = new THREE.Vector2(ns, ns)
  // roughness maps carry absolute values; material.roughness becomes the multiplier
  mat.roughness = o.roughnessMul ?? 1
  mat.color.set(0xffffff)
  mat.needsUpdate = true
}

function flush(key: TexKey) {
  const e = texDB.get(key)
  if (!e || e.ready) return
  // a failed download leaves image null -> never apply maps, keep fallback color
  e.ready = !!(e.albedo.image && e.normal.image && e.rough.image)
  const pend = e.pending
  e.pending = []
  if (!e.ready) return
  for (const p of pend) applyMaps(key, p.mat, p.rx, p.ry, p.o)
}

/** Material factory: textured (cached) or flat-color fallback. */
export function texMat(key: TexKey, rx = 1, ry = 1, o: MatOpts = {}): THREE.MeshStandardMaterial {
  const q = (v: number) => Math.max(0.25, Math.round(v * 4) / 4)
  const rrx = q(rx), rry = q(ry)
  const ck = `${key}|${rrx}|${rry}|${o.color ?? ''}|${o.metalness ?? ''}|${o.roughnessMul ?? ''}|${o.normalScale ?? ''}`
  const hit = matCache.get(ck)
  if (hit) return hit
  const f = FALLBACK[key]
  const mat = new THREE.MeshStandardMaterial({
    color: o.color ?? f.color,
    metalness: o.metalness ?? f.metalness,
    roughness: f.roughness,
  })
  const e = getTex(key)
  if (e.ready) applyMaps(key, mat, rrx, rry, o)
  else e.pending.push({ mat, rx: rrx, ry: rry, o })
  matCache.set(ck, mat)
  return mat
}

const matCache = new Map<string, THREE.MeshStandardMaterial>()

/** Kick off all texture downloads early so viewmodels never pop in mid-game. */
export function preloadWeaponTextures() {
  for (const k of Object.keys(FALLBACK) as TexKey[]) getTex(k)
}

// ---------------------------------------------------------------- geometry cache
const geoCache = new Map<string, THREE.BufferGeometry>()

export function box(w: number, h: number, d: number): THREE.BoxGeometry {
  const k = `b${w.toFixed(3)}:${h.toFixed(3)}:${d.toFixed(3)}`
  let g = geoCache.get(k) as THREE.BoxGeometry | undefined
  if (!g) { g = new THREE.BoxGeometry(w, h, d); geoCache.set(k, g) }
  return g
}

export function cyl(r: number, len: number, seg = 12): THREE.CylinderGeometry {
  const k = `c${r.toFixed(3)}:${len.toFixed(3)}:${seg}`
  let g = geoCache.get(k) as THREE.CylinderGeometry | undefined
  if (!g) { g = new THREE.CylinderGeometry(r, r, len, seg); geoCache.set(k, g) }
  return g
}

function repeatFor(geo: THREE.BufferGeometry, density: number): [number, number] {
  const p = (geo as THREE.BoxGeometry).parameters
  if (p && typeof p.width === 'number') {
    const dims = [p.width, p.height, p.depth].sort((a, b) => b - a)
    return [Math.max(0.35, dims[0] * density), Math.max(0.35, dims[1] * density)]
  }
  const c = (geo as THREE.CylinderGeometry).parameters
  if (c && typeof c.radiusTop === 'number') {
    const r = Math.max(c.radiusTop, c.radiusBottom)
    return [Math.max(0.35, Math.PI * 2 * r * density * 0.55), Math.max(0.35, c.height * density)]
  }
  return [1, 1]
}

/** Add a textured mesh part; auto texture-repeat from its geometry size. */
function P(parent: THREE.Object3D, geo: THREE.BufferGeometry, key: TexKey, o: MatOpts,
  x: number, y: number, z: number, rx = 0, ry = 0, rz = 0): THREE.Mesh {
  const f = FALLBACK[key]
  const [arx, ary] = repeatFor(geo, o.density ?? f.density)
  const mat = texMat(key, o.rx ?? arx, o.ry ?? ary, o)
  const m = new THREE.Mesh(geo, mat)
  m.position.set(x, y, z)
  m.rotation.set(rx, ry, rz)
  parent.add(m)
  return m
}

/** Flat basic material for lenses / LED dots / sights. */
function basic(color: number, parent: THREE.Object3D, geo: THREE.BufferGeometry,
  x: number, y: number, z: number, rx = 0, ry = 0, rz = 0): THREE.Mesh {
  const m = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color }))
  m.position.set(x, y, z)
  m.rotation.set(rx, ry, rz)
  parent.add(m)
  return m
}

const q = (deg: number) => (deg * Math.PI) / 180

// ---------------------------------------------------------------- gloves
const CUFF: Record<TeamId, number> = { T: 0x9a7f4e, CT: 0x2c4a6e }

/**
 * Right hand + forearm wrapped around a grip point (local gun coords),
 * plus optional left support hand at a foregrip.
 */
function buildGloves(g: THREE.Object3D, team: TeamId,
  grip: { x: number; y: number; z: number; rx?: number },
  left?: { x: number; y: number; z: number; rx?: number }) {
  const rx = grip.rx ?? 0.25
  // palm wraps the grip
  P(g, box(0.055, 0.075, 0.105), 'glove_fabric', { color: 0x232527 }, grip.x + 0.012, grip.y - 0.01, grip.z + 0.01, rx)
  // fingers over the front strap
  for (let i = 0; i < 3; i++) {
    P(g, box(0.05, 0.017, 0.028), 'glove_fabric', { color: 0x1d1f21 },
      grip.x + 0.014, grip.y - 0.031 - i * 0.02, grip.z - 0.028 - i * 0.004, rx)
  }
  // thumb on the left/rear
  P(g, box(0.017, 0.045, 0.022), 'glove_fabric', { color: 0x1d1f21 }, grip.x - 0.012, grip.y - 0.012, grip.z + 0.04, 0.1)
  // cuff band (team color)
  P(g, box(0.075, 0.075, 0.045), 'polymer_black', { color: CUFF[team], density: 2 },
    grip.x + 0.028, grip.y - 0.06, grip.z + 0.075, rx)
  // forearm running down-back-right toward the camera
  P(g, box(0.07, 0.072, 0.32), 'glove_fabric', {},
    grip.x + 0.052, grip.y - 0.145, grip.z + 0.235, 0.52, -0.22, -0.08)

  if (left) {
    const lrx = left.rx ?? 0.3
    P(g, box(0.055, 0.075, 0.1), 'glove_fabric', { color: 0x232527 }, left.x - 0.006, left.y - 0.015, left.z, lrx)
    P(g, box(0.05, 0.016, 0.03), 'glove_fabric', { color: 0x1d1f21 }, left.x - 0.004, left.y - 0.04, left.z + 0.005, lrx)
    P(g, box(0.075, 0.075, 0.045), 'polymer_black', { color: CUFF[team], density: 2 },
      left.x - 0.026, left.y - 0.07, left.z + 0.08, lrx)
    P(g, box(0.07, 0.072, 0.3), 'glove_fabric', {},
      left.x - 0.045, left.y - 0.16, left.z + 0.23, 0.5, 0.24, 0.08)
  }
}

// ---------------------------------------------------------------- AK-47
function buildAK(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // receiver + dust cover
  P(g, box(0.058, 0.07, 0.30), 'steel_blued', {}, 0, 0.005, -0.15)
  P(g, box(0.054, 0.026, 0.26), 'steel_blued', { roughnessMul: 0.9 }, 0, 0.045, -0.16)
  // rear sight block + front sight
  P(g, box(0.05, 0.02, 0.03), 'steel_blued', {}, 0, 0.058, -0.30)
  P(g, box(0.012, 0.045, 0.012), 'steel_blued', {}, 0, 0.05, -0.62)
  P(g, box(0.004, 0.03, 0.012), 'steel_blued', {}, 0.014, 0.05, -0.62)
  P(g, box(0.004, 0.03, 0.012), 'steel_blued', {}, -0.014, 0.05, -0.62)
  // gas system
  P(g, box(0.024, 0.03, 0.03), 'steel_blued', {}, 0, 0.033, -0.50)
  P(g, cyl(0.009, 0.24), 'steel_blued', {}, 0, 0.045, -0.42, q(90))
  // barrel + slant brake
  P(g, cyl(0.010, 0.40), 'steel_blued', {}, 0, 0.01, -0.55, q(90))
  P(g, cyl(0.0135, 0.035), 'steel_blued', {}, 0, 0.01, -0.755, q(90))
  P(g, box(0.013, 0.024, 0.03), 'steel_blued', {}, 0.002, 0.004, -0.768, 0, 0, -0.35)
  // wood furniture
  P(g, box(0.052, 0.042, 0.16), 'wood_laminate', {}, 0, 0.0, -0.38)
  P(g, box(0.046, 0.028, 0.13), 'wood_laminate', { roughnessMul: 0.9 }, 0, 0.031, -0.36)
  P(g, box(0.04, 0.062, 0.24), 'wood_laminate', {}, 0, -0.018, 0.15, 0.1)
  P(g, box(0.043, 0.09, 0.012), 'steel_blued', {}, 0, -0.035, 0.272)
  // pistol grip + trigger guard
  P(g, box(0.036, 0.09, 0.05), 'wood_laminate', { color: 0x7a4a20 }, 0, -0.062, 0.022, 0.3)
  P(g, box(0.03, 0.005, 0.052), 'steel_blued', {}, 0, -0.045, -0.02)
  // charging handle
  P(g, box(0.024, 0.01, 0.018), 'steel_blued', {}, 0.038, 0.032, -0.25)
  // curved magazine (progressive pitch segments)
  const mag = new THREE.Group()
  g.add(mag)
  for (let i = 0; i < 4; i++) {
    P(mag, box(0.047, 0.05, 0.078), 'metal_dark', { roughnessMul: 0.8 },
      0, -0.062 - i * 0.047, -0.135 - i * 0.021, -0.24 * i)
  }
  P(mag, box(0.05, 0.014, 0.085), 'metal_dark', {}, 0, -0.232, -0.182, -0.75)
  buildGloves(g, team, { x: 0, y: -0.055, z: 0.03, rx: 0.3 }, { x: 0, y: -0.03, z: -0.36, rx: 0.25 })
  return { group: g, tip: new THREE.Vector3(0, 0.01, -0.78), mag, eject: new THREE.Vector3(0.034, 0.02, -0.22) }
}

// ---------------------------------------------------------------- M4A4
function buildM4(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // receivers
  P(g, box(0.05, 0.05, 0.24), 'polymer_black', { color: 0x26292c }, 0, 0.022, -0.13)
  P(g, box(0.048, 0.06, 0.12), 'polymer_black', { color: 0x222527 }, 0, -0.03, -0.09)
  // flat-top rail with notch slots
  P(g, box(0.03, 0.01, 0.27), 'polymer_black', { color: 0x2a2d30 }, 0, 0.052, -0.13)
  for (let i = 0; i < 9; i++) {
    P(g, box(0.032, 0.006, 0.012), 'metal_dark', { color: 0x101214 }, 0, 0.053, -0.26 + i * 0.03)
  }
  // barrel + birdcage
  P(g, cyl(0.009, 0.28), 'steel_blued', {}, 0, 0.014, -0.41, q(90))
  P(g, cyl(0.0125, 0.05), 'steel_blued', {}, 0, 0.014, -0.575, q(90))
  P(g, box(0.004, 0.01, 0.035), 'metal_dark', { color: 0x101214 }, 0.012, 0.014, -0.575)
  P(g, box(0.004, 0.01, 0.035), 'metal_dark', { color: 0x101214 }, -0.012, 0.014, -0.575)
  // front sight tower (triangle)
  P(g, box(0.012, 0.05, 0.012), 'polymer_black', { color: 0x26292c }, 0.012, 0.048, -0.28, 0, 0, 0.3)
  P(g, box(0.012, 0.05, 0.012), 'polymer_black', { color: 0x26292c }, -0.012, 0.048, -0.28, 0, 0, -0.3)
  P(g, box(0.006, 0.018, 0.006), 'metal_dark', {}, 0, 0.082, -0.28)
  // railed handguard
  P(g, box(0.052, 0.05, 0.22), 'polymer_black', { color: 0x25282a }, 0, 0.014, -0.33)
  for (let i = 0; i < 5; i++) {
    P(g, box(0.054, 0.006, 0.014), 'metal_dark', { color: 0x101214 }, 0, 0.043, -0.26 - i * 0.035)
  }
  P(g, box(0.006, 0.03, 0.2), 'metal_dark', { color: 0x16181a }, 0.028, 0.006, -0.33)
  P(g, box(0.006, 0.03, 0.2), 'metal_dark', { color: 0x16181a }, -0.028, 0.006, -0.33)
  // charging handle + rear sight
  P(g, box(0.03, 0.012, 0.032), 'polymer_black', { color: 0x26292c }, 0, 0.05, 0.0)
  P(g, box(0.03, 0.014, 0.02), 'polymer_black', { color: 0x26292c }, 0, 0.062, 0.005)
  // magazine
  const mag = new THREE.Group()
  g.add(mag)
  P(mag, box(0.038, 0.125, 0.058), 'polymer_black', { color: 0x1f2224 }, 0, -0.108, -0.065, -0.07)
  P(mag, box(0.042, 0.014, 0.064), 'polymer_black', { color: 0x191c1e }, 0, -0.172, -0.07, -0.07)
  // stock: tube + butt
  P(g, cyl(0.016, 0.15), 'polymer_black', { color: 0x2a2d30 }, 0, 0.028, 0.115, q(90))
  P(g, box(0.04, 0.09, 0.1), 'polymer_black', { color: 0x26292c }, 0, 0.0, 0.22)
  P(g, box(0.042, 0.095, 0.015), 'polymer_black', { color: 0x16181a }, 0, 0.0, 0.272)
  P(g, box(0.036, 0.02, 0.08), 'polymer_black', { color: 0x26292c }, 0, 0.055, 0.18, -0.15)
  // trigger
  P(g, box(0.006, 0.028, 0.008), 'metal_dark', { color: 0x101214 }, 0, -0.035, -0.015, 0.15)
  buildGloves(g, team, { x: 0, y: -0.05, z: 0.03, rx: 0.28 }, { x: 0, y: -0.02, z: -0.33, rx: 0.3 })
  return { group: g, tip: new THREE.Vector3(0, 0.014, -0.62), mag, eject: new THREE.Vector3(0.03, 0.035, -0.15) }
}

// ---------------------------------------------------------------- AWP
function buildAWP(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // receiver
  P(g, box(0.05, 0.06, 0.28), 'steel_blued', {}, 0, 0.01, -0.12)
  // barrel + muzzle brake
  P(g, cyl(0.012, 0.52), 'steel_blued', {}, 0, 0.02, -0.52, q(90))
  P(g, cyl(0.017, 0.062), 'steel_blued', {}, 0, 0.02, -0.79, q(90))
  for (let i = 0; i < 3; i++) {
    P(g, box(0.005, 0.012, 0.03), 'metal_dark', { color: 0x101214 }, 0.017, 0.02, -0.76 - i * 0.02)
    P(g, box(0.005, 0.012, 0.03), 'metal_dark', { color: 0x101214 }, -0.017, 0.02, -0.76 - i * 0.02)
  }
  // scope: tube + bells + lens + turrets + rings
  P(g, cyl(0.021, 0.26, 16), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.088, -0.16, q(90))
  P(g, cyl(0.03, 0.055, 16), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.088, -0.30, q(90))
  P(g, cyl(0.025, 0.045, 16), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.088, -0.015, q(90))
  basic(0x24384a, g, cyl(0.027, 0.003, 16), 0, 0.088, -0.326, q(90))       // objective lens
  basic(0x2c3a2a, g, cyl(0.022, 0.003, 16), 0, 0.088, 0.009, q(90))        // ocular lens
  P(g, cyl(0.009, 0.018, 12), 'metal_dark', {}, 0, 0.118, -0.16)           // elevation turret
  P(g, cyl(0.009, 0.018, 12), 'metal_dark', {}, 0.03, 0.088, -0.16, 0, 0, q(90)) // windage turret
  P(g, box(0.02, 0.045, 0.026), 'metal_dark', {}, 0, 0.055, -0.07)         // front mount
  P(g, box(0.02, 0.045, 0.026), 'metal_dark', {}, 0, 0.055, -0.24)         // rear mount
  // chassis / stock in olive enamel
  P(g, box(0.052, 0.05, 0.17), 'enamel_od', {}, 0, 0.0, -0.28)             // forend
  P(g, box(0.05, 0.085, 0.28), 'enamel_od', {}, 0, -0.005, 0.1)            // butt frame
  P(g, box(0.045, 0.1, 0.06), 'enamel_od', {}, 0, -0.065, 0.03, 0.18)      // grip
  P(g, box(0.045, 0.03, 0.13), 'enamel_od', {}, 0, 0.048, 0.05)            // cheek riser
  P(g, box(0.052, 0.11, 0.02), 'polymer_black', { color: 0x16181a }, 0, -0.01, 0.245) // butt pad
  // magazine box
  const mag = new THREE.Group()
  g.add(mag)
  P(mag, box(0.04, 0.075, 0.09), 'polymer_black', { color: 0x1f2224 }, 0, -0.062, -0.10, -0.08)
  P(mag, box(0.044, 0.012, 0.095), 'polymer_black', { color: 0x16181a }, 0, -0.102, -0.104, -0.08)
  // bolt assembly (animates: lift, pull, push, drop)
  const bolt = new THREE.Group()
  g.add(bolt)
  P(bolt, cyl(0.007, 0.075, 10), 'steel_blued', { roughnessMul: 0.5 }, 0.028, 0.048, 0.02, q(90))
  P(bolt, cyl(0.005, 0.032, 8), 'steel_blued', {}, 0.052, 0.028, 0.02, 0, 0, q(60))
  P(bolt, new THREE.SphereGeometry(0.009, 10, 8), 'steel_blued', { roughnessMul: 0.5 }, 0.066, 0.011, 0.02)
  buildGloves(g, team, { x: 0, y: -0.055, z: 0.05, rx: 0.3 }, { x: 0, y: -0.03, z: -0.3, rx: 0.25 })
  return { group: g, tip: new THREE.Vector3(0, 0.02, -0.84), mag, bolt, eject: new THREE.Vector3(0.034, 0.035, -0.1), muzzleLen: 0.86 }
}

// ---------------------------------------------------------------- MP5-SD
function buildMP5(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // receiver tube + grip frame
  P(g, cyl(0.024, 0.24, 14), 'metal_dark', { color: 0x232629 }, 0, 0.012, -0.15, q(90))
  P(g, box(0.04, 0.05, 0.11), 'polymer_black', { color: 0x222527 }, 0, -0.018, -0.055)
  P(g, box(0.036, 0.028, 0.05), 'polymer_black', { color: 0x1f2224 }, 0, -0.05, -0.105)
  // suppressor with vent rings
  P(g, cyl(0.023, 0.19, 14), 'metal_dark', {}, 0, 0.012, -0.36, q(90))
  for (let i = 0; i < 3; i++) {
    P(g, cyl(0.0245, 0.008, 14), 'metal_dark', { color: 0x16181a }, 0, 0.012, -0.30 - i * 0.06, q(90))
  }
  // hooded front sight + cocking handle
  P(g, box(0.004, 0.03, 0.004), 'metal_dark', { color: 0x16181a }, 0, 0.052, -0.255)
  P(g, box(0.024, 0.004, 0.008), 'metal_dark', { color: 0x16181a }, 0, 0.062, -0.255)
  P(g, box(0.004, 0.024, 0.008), 'metal_dark', { color: 0x16181a }, 0.012, 0.052, -0.255)
  P(g, box(0.004, 0.024, 0.008), 'metal_dark', { color: 0x16181a }, -0.012, 0.052, -0.255)
  P(g, box(0.022, 0.008, 0.06), 'steel_blued', {}, -0.032, 0.02, -0.19, 0, 0, 0.25)
  // rear drum sight
  P(g, cyl(0.012, 0.012, 10), 'metal_dark', { color: 0x16181a }, 0, 0.05, -0.03, q(90))
  // magazine (slight progressive curve)
  const mag = new THREE.Group()
  g.add(mag)
  for (let i = 0; i < 3; i++) {
    P(mag, box(0.025, 0.05, 0.05), 'polymer_black', { color: 0x1f2224 },
      0, -0.075 - i * 0.048, -0.105 - i * 0.014, -0.16 * i)
  }
  P(mag, box(0.028, 0.012, 0.055), 'polymer_black', { color: 0x16181a }, 0, -0.212, -0.126, -0.35)
  // fixed stock + butt pad
  P(g, box(0.038, 0.062, 0.19), 'polymer_black', { color: 0x25282a }, 0, 0.008, 0.115)
  P(g, box(0.041, 0.085, 0.015), 'polymer_black', { color: 0x16181a }, 0, 0.0, 0.215)
  // trigger
  P(g, box(0.005, 0.026, 0.007), 'metal_dark', { color: 0x101214 }, 0, -0.032, -0.03, 0.12)
  buildGloves(g, team, { x: 0, y: -0.05, z: 0.0, rx: 0.28 }, { x: 0, y: -0.03, z: -0.26, rx: 0.3 })
  return { group: g, tip: new THREE.Vector3(0, 0.012, -0.465), mag, eject: new THREE.Vector3(0.03, 0.035, -0.11) }
}

// ---------------------------------------------------------------- Desert Eagle
function buildDeagle(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // slide + top rib + barrel
  const slide = P(g, box(0.043, 0.05, 0.21), 'metal_dark', { roughnessMul: 0.8, normalScale: 0.8 }, 0, 0.028, -0.08)
  P(g, box(0.014, 0.014, 0.2), 'steel_blued', { roughnessMul: 0.5 }, 0, 0.06, -0.08)
  P(g, cyl(0.0095, 0.028), 'steel_blued', { roughnessMul: 0.5 }, 0, 0.03, -0.192, q(90))
  // slide serrations
  for (let i = 0; i < 4; i++) {
    P(g, box(0.046, 0.03, 0.003), 'metal_dark', { color: 0x101214 }, 0, 0.032, -0.005 - i * 0.008)
  }
  // sights
  P(g, box(0.006, 0.01, 0.008), 'metal_dark', { color: 0x565b60 }, 0, 0.058, -0.172)
  P(g, box(0.02, 0.009, 0.01), 'metal_dark', { color: 0x565b60 }, 0, 0.058, 0.018)
  // frame + grip
  P(g, box(0.04, 0.036, 0.13), 'metal_dark', { color: 0x232629, roughnessMul: 0.9 }, 0, -0.002, -0.03)
  P(g, box(0.04, 0.115, 0.055), 'polymer_black', { density: 9 }, 0, -0.075, 0.018, 0.24)
  // hammer + trigger
  P(g, box(0.008, 0.02, 0.012), 'metal_dark', { color: 0x101214 }, 0, 0.05, 0.022, -0.5)
  P(g, box(0.006, 0.03, 0.008), 'metal_dark', { color: 0x101214 }, 0, -0.028, -0.045, 0.2)
  // trigger guard
  P(g, box(0.03, 0.005, 0.055), 'metal_dark', { color: 0x232629 }, 0, -0.052, -0.045)
  // magazine inside grip
  const mag = new THREE.Group()
  g.add(mag)
  P(mag, box(0.034, 0.1, 0.048), 'metal_dark', { color: 0x1b1e21 }, 0, -0.072, 0.012, 0.24)
  P(mag, box(0.042, 0.012, 0.06), 'metal_dark', { color: 0x141618 }, 0, -0.128, 0.026, 0.24)
  buildGloves(g, team, { x: 0, y: -0.07, z: 0.03, rx: 0.3 })
  return { group: g, tip: new THREE.Vector3(0, 0.03, -0.21), mag, slide, eject: new THREE.Vector3(0.026, 0.045, -0.12) }
}

// ---------------------------------------------------------------- Glock-18 / USP-S
function buildPistol(weapon: 'glock' | 'usp', team: TeamId): ViewModel {
  const g = new THREE.Group()
  const usp = weapon === 'usp'
  const slideLen = usp ? 0.195 : 0.185
  const slideH = usp ? 0.048 : 0.042
  const slideCol = usp ? 0x2c3033 : 0x26292c
  // slide
  const slide = P(g, box(usp ? 0.038 : 0.036, slideH, slideLen), 'metal_dark',
    { color: slideCol, roughnessMul: 0.8, normalScale: 0.8 }, 0, 0.02, -slideLen / 2 + 0.02)
  // barrel + muzzle
  if (usp) {
    P(g, cyl(0.0165, 0.135, 14), 'metal_dark', { roughnessMul: 0.75 }, 0, 0.012, -0.215, q(90))
  } else {
    P(g, cyl(0.0075, 0.022), 'steel_blued', { roughnessMul: 0.5 }, 0, 0.014, -0.172, q(90))
  }
  // slide serrations
  for (let i = 0; i < 4; i++) {
    P(g, box((usp ? 0.04 : 0.038), 0.026, 0.0025), 'metal_dark', { color: 0x0f1113 }, 0, 0.022, 0.045 - i * 0.007)
  }
  // sights (white dots)
  P(g, box(0.005, 0.009, 0.007), 'metal_dark', { color: 0x50555a }, 0, 0.048, -slideLen / 2 - 0.075)
  P(g, box(0.016, 0.008, 0.008), 'metal_dark', { color: 0x50555a }, 0, 0.048, 0.055)
  basic(0xf4f4f4, g, box(0.004, 0.004, 0.003), 0, 0.053, -slideLen / 2 - 0.075)
  // frame + rail + magwell flare
  P(g, box(0.034, 0.03, 0.13), 'polymer_black', { color: 0x222527 }, 0, -0.008, -0.04)
  P(g, box(0.028, 0.008, 0.05), 'polymer_black', { color: 0x191c1e }, 0, -0.026, -0.105)
  P(g, box(0.04, 0.012, 0.052), 'polymer_black', { color: 0x191c1e }, 0, -0.098, 0.028, 0.2)
  // trigger + guard
  P(g, box(0.005, 0.026, 0.007), 'metal_dark', { color: 0x101214 }, 0, -0.025, -0.05, 0.15)
  P(g, box(0.026, 0.004, 0.05), 'polymer_black', { color: 0x191c1e }, 0, -0.046, -0.05)
  // grip (heavy stipple) + magazine
  P(g, box(0.034, 0.105, 0.048), 'polymer_black', { density: 9 }, 0, -0.068, 0.015, 0.22)
  const mag = new THREE.Group()
  g.add(mag)
  P(mag, box(0.03, 0.095, 0.042), 'metal_dark', { color: 0x1b1e21 }, 0, -0.066, 0.012, 0.22)
  P(mag, box(0.036, 0.011, 0.05), 'polymer_black', { color: 0x141618 }, 0, -0.118, 0.024, 0.22)
  buildGloves(g, team, { x: 0, y: -0.065, z: 0.028, rx: 0.3 })
  const tipZ = usp ? -0.285 : -0.185
  return { group: g, tip: new THREE.Vector3(0, 0.014, tipZ), mag, slide, eject: new THREE.Vector3(0.022, 0.038, -0.1) }
}

// ---------------------------------------------------------------- knife (M9 bayonet style)
function buildKnife(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // blade (bright ground steel) + clip point tip + fuller groove
  P(g, box(0.012, 0.036, 0.17), 'metal_dark',
    { color: 0xcdd3d9, metalness: 1.0, roughnessMul: 0.35, normalScale: 0.7 }, 0, 0.016, -0.14)
  P(g, box(0.012, 0.026, 0.06), 'metal_dark',
    { color: 0xcdd3d9, metalness: 1.0, roughnessMul: 0.35, normalScale: 0.7 }, 0, 0.024, -0.24, -0.14)
  P(g, box(0.013, 0.009, 0.11), 'metal_dark',
    { color: 0x6f767c, metalness: 1.0, roughnessMul: 0.6 }, 0, 0.024, -0.115)
  // crossguard + handle + pommel
  P(g, box(0.012, 0.08, 0.016), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.002, -0.045)
  P(g, box(0.023, 0.033, 0.105), 'polymer_black', { density: 9 }, 0, 0.0, 0.016)
  for (let i = 0; i < 3; i++) {
    P(g, box(0.0245, 0.006, 0.012), 'polymer_black', { color: 0x14161a, density: 9 }, 0, -0.008 + i * 0.008, -0.012 + i * 0.032)
  }
  P(g, box(0.026, 0.037, 0.022), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.0, 0.075)
  buildGloves(g, team, { x: 0, y: 0.0, z: 0.02, rx: 0.12 })
  return { group: g, tip: new THREE.Vector3(0, 0.022, -0.28) }
}

// ---------------------------------------------------------------- C4
let keypadTex: THREE.Texture | null = null
function getKeypadTex(): THREE.Texture {
  if (keypadTex) return keypadTex
  const c = document.createElement('canvas')
  c.width = 256; c.height = 256
  const ctx = c.getContext('2d')!
  ctx.fillStyle = '#181b16'
  ctx.fillRect(0, 0, 256, 256)
  ctx.fillStyle = '#232720'
  for (let gy = 0; gy < 3; gy++) for (let gx = 0; gx < 3; gx++) {
    ctx.fillRect(16 + gx * 80, 16 + gy * 80, 64, 64)
  }
  ctx.fillStyle = '#c8d4b0'
  ctx.font = 'bold 40px monospace'
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9']
  keys.forEach((k, i) => ctx.fillText(k, 48 + (i % 3) * 80, 48 + Math.floor(i / 3) * 80))
  keypadTex = new THREE.CanvasTexture(c)
  keypadTex.colorSpace = THREE.SRGBColorSpace
  return keypadTex
}

function buildC4(team: TeamId): ViewModel {
  const g = new THREE.Group()
  // explosive block body
  P(g, box(0.15, 0.06, 0.19), 'enamel_od', { color: 0x5a5c42, roughnessMul: 1.1 }, 0, 0, -0.09)
  // straps
  P(g, box(0.152, 0.062, 0.013), 'polymer_black', { color: 0x121311, density: 2 }, 0, 0, -0.03)
  P(g, box(0.152, 0.062, 0.013), 'polymer_black', { color: 0x121311, density: 2 }, 0, 0, -0.15)
  // PCB panel + components
  P(g, box(0.11, 0.005, 0.14), 'pcb_green', { normalScale: 1.3 }, -0.012, 0.032, -0.10)
  for (let i = 0; i < 3; i++) {
    P(g, box(0.018, 0.007, 0.028), 'metal_dark', { color: 0x0c0d0e }, -0.042 + i * 0.03, 0.038, -0.135)
  }
  P(g, cyl(0.006, 0.014, 8), 'metal_dark', { color: 0x1e2226 }, -0.03, 0.039, -0.085)
  P(g, cyl(0.005, 0.012, 8), 'metal_dark', { color: 0x3a2e1a }, 0.012, 0.038, -0.075)
  P(g, box(0.03, 0.012, 0.035), 'metal_dark', { color: 0x101214 }, 0.032, 0.038, -0.135)
  // keypad
  const kp = new THREE.Mesh(box(0.05, 0.006, 0.055), new THREE.MeshStandardMaterial({
    map: getKeypadTex(), roughness: 0.75, metalness: 0.1,
  }))
  kp.position.set(-0.012, 0.033, -0.035)
  g.add(kp)
  // screen + LED (blinks)
  basic(0x0d1f0d, g, box(0.03, 0.004, 0.018), -0.012, 0.033, -0.005)
  const led = basic(0xff2020, g, box(0.008, 0.006, 0.008), 0.03, 0.034, -0.005)
  // det wires to the side
  P(g, cyl(0.003, 0.05, 6), 'metal_dark', { color: 0x181a1c }, 0.07, 0.03, -0.06, 0, 0, q(55))
  P(g, cyl(0.003, 0.04, 6), 'metal_dark', { color: 0x301c10 }, 0.065, 0.03, -0.1, 0, 0, q(70))
  // left hand cupping the block from below
  P(g, box(0.055, 0.06, 0.1), 'glove_fabric', { color: 0x232527 }, 0.01, -0.062, -0.09)
  P(g, box(0.075, 0.075, 0.045), 'polymer_black', { color: CUFF[team], density: 2 }, 0.045, -0.12, -0.03, 0.4)
  P(g, box(0.07, 0.072, 0.3), 'glove_fabric', {}, 0.08, -0.19, 0.09, 0.55, -0.25, -0.08)
  return { group: g, tip: new THREE.Vector3(0, 0, -0.2), led }
}

// ---------------------------------------------------------------- dispatcher
const VM_BASE = new THREE.Vector3(0.26, -0.24, -0.45)

/** Build the first-person viewmodel for a weapon (cached by the engine). */
export function buildViewModel(weapon: WeaponId, team: TeamId): ViewModel {
  switch (weapon) {
    case 'ak47': return buildAK(team)
    case 'm4': return buildM4(team)
    case 'awp': return buildAWP(team)
    case 'mp5': return buildMP5(team)
    case 'deagle': return buildDeagle(team)
    case 'glock': case 'usp': return buildPistol(weapon, team)
    case 'knife': return buildKnife(team)
    case 'c4': return buildC4(team)
    default: return buildKnife(team)
  }
}

/** Base position of a viewmodel group relative to the camera. */
export function vmBase(weapon: WeaponId): THREE.Vector3 {
  const off = weapon === 'c4' ? new THREE.Vector3(-0.1, -0.075, 0.02)
    : weapon === 'knife' ? new THREE.Vector3(0.24, -0.25, -0.4)
    : weapon === 'awp' ? new THREE.Vector3(0.24, -0.235, -0.43)
    : VM_BASE.clone()
  return off
}

// ---------------------------------------------------------------- remote player guns
/**
 * Low-detail textured gun held by remote players. Origin at the grip,
 * muzzle toward -z; position it at the hand in players.ts.
 */
export function buildRemoteGun(weaponId: string): THREE.Group {
  const g = new THREE.Group()
  switch (weaponId) {
    case 'ak47':
      P(g, box(0.05, 0.06, 0.3), 'steel_blued', {}, 0, 0, 0.02)
      P(g, cyl(0.009, 0.34), 'steel_blued', {}, 0, 0.01, -0.24, q(90))
      P(g, box(0.04, 0.045, 0.14), 'wood_laminate', {}, 0, 0.0, -0.16)
      P(g, box(0.045, 0.1, 0.07), 'metal_dark', { roughnessMul: 0.8 }, 0, -0.09, -0.03, -0.2)
      P(g, box(0.035, 0.05, 0.18), 'wood_laminate', {}, 0, -0.01, 0.2)
      break
    case 'm4':
      P(g, box(0.045, 0.05, 0.24), 'polymer_black', { color: 0x26292c }, 0, 0, 0)
      P(g, cyl(0.008, 0.26), 'steel_blued', {}, 0, 0.01, -0.22, q(90))
      P(g, box(0.04, 0.045, 0.18), 'polymer_black', { color: 0x25282a }, 0, 0, -0.16)
      P(g, box(0.035, 0.1, 0.05), 'polymer_black', { color: 0x1f2224 }, 0, -0.08, -0.02, -0.06)
      P(g, box(0.035, 0.07, 0.14), 'polymer_black', { color: 0x26292c }, 0, 0, 0.2)
      break
    case 'awp':
      P(g, box(0.045, 0.055, 0.26), 'steel_blued', {}, 0, 0, 0)
      P(g, cyl(0.011, 0.44), 'steel_blued', {}, 0, 0.015, -0.33, q(90))
      P(g, cyl(0.018, 0.2, 12), 'metal_dark', { roughnessMul: 0.7 }, 0, 0.07, -0.06, q(90))
      P(g, box(0.045, 0.08, 0.24), 'enamel_od', {}, 0, -0.01, 0.18)
      P(g, box(0.035, 0.07, 0.08), 'polymer_black', { color: 0x1f2224 }, 0, -0.06, -0.02, -0.06)
      break
    case 'mp5':
      P(g, cyl(0.022, 0.22, 12), 'metal_dark', { color: 0x232629 }, 0, 0.01, -0.02, q(90))
      P(g, cyl(0.02, 0.16, 12), 'metal_dark', {}, 0, 0.01, -0.2, q(90))
      P(g, box(0.03, 0.08, 0.05), 'polymer_black', { color: 0x1f2224 }, 0, -0.07, 0, -0.1)
      P(g, box(0.032, 0.06, 0.14), 'polymer_black', { color: 0x25282a }, 0, 0, 0.16)
      break
    case 'deagle':
      P(g, box(0.038, 0.045, 0.2), 'metal_dark', { roughnessMul: 0.8 }, 0, 0.015, -0.05)
      P(g, box(0.036, 0.09, 0.05), 'polymer_black', { density: 9 }, 0, -0.06, 0.03, 0.22)
      break
    case 'glock': case 'usp':
      P(g, box(0.032, 0.038, 0.16), 'metal_dark', { color: 0x26292c, roughnessMul: 0.8 }, 0, 0.01, -0.04)
      if (weaponId === 'usp') P(g, cyl(0.014, 0.1, 12), 'metal_dark', { roughnessMul: 0.75 }, 0, 0.01, -0.16, q(90))
      P(g, box(0.03, 0.08, 0.045), 'polymer_black', { density: 9 }, 0, -0.055, 0.02, 0.2)
      break
    case 'knife':
      P(g, box(0.01, 0.028, 0.14), 'metal_dark', { color: 0xcdd3d9, metalness: 1.0, roughnessMul: 0.35 }, 0, 0.01, -0.1)
      P(g, box(0.02, 0.03, 0.08), 'polymer_black', { density: 9 }, 0, 0, 0.02)
      break
    case 'c4':
      P(g, box(0.13, 0.05, 0.16), 'enamel_od', { color: 0x5a5c42, roughnessMul: 1.1 }, 0, 0, -0.02)
      basic(0xff2020, g, box(0.01, 0.006, 0.01), 0.02, 0.028, 0.04)
      break
    default:
      P(g, box(0.045, 0.06, 0.4), 'metal_dark', {}, 0, 0, -0.1)
  }
  return g
}
